.custom-4a0ee5c7-58e5-46ab-8609-b29f7920ee63.camediaload .load-media-element,
.custom-4a0ee5c7-58e5-46ab-8609-b29f7920ee63 .camediaload .load-media-element{
    transition: opacity 0.4s ease-out, transform {{duration}} {{easing}} !important;
    transform: translate3d(0px, 0px, 0px) scale(1) !important;
}
.custom-4a0ee5c7-58e5-46ab-8609-b29f7920ee63.camediaload:hover .load-media-element,
.custom-4a0ee5c7-58e5-46ab-8609-b29f7920ee63 .camediaload:hover .load-media-element{
    transform: translate3d(0px, 0px, 0px) scale({{scale}}) !important;
}

.custom-4a0ee5c7-58e5-46ab-8609-b29f7920ee63.camediaload .load-media-element-clone,
.custom-4a0ee5c7-58e5-46ab-8609-b29f7920ee63 .camediaload .load-media-element-clone{
    opacity: 0;
    transition: opacity {{duration}} {{easing}}, transform {{duration}} {{easing}} !important;
    transform: translate3d(0px, 0px, 0px) scale(1) !important;
}
.custom-4a0ee5c7-58e5-46ab-8609-b29f7920ee63.camediaload:hover .load-media-element-clone,
.custom-4a0ee5c7-58e5-46ab-8609-b29f7920ee63 .camediaload:hover .load-media-element-clone{
    opacity: 1;
    transform: translate3d(0px, 0px, 0px) scale({{scale}}) !important;
}

.custom-4a0ee5c7-58e5-46ab-8609-b29f7920ee63.camediaload .layer-color,
.custom-4a0ee5c7-58e5-46ab-8609-b29f7920ee63 .camediaload .layer-color{
    transition: background-color {{duration}} {{easing}};
    background-color: {{color:layerColor}}
}
.custom-4a0ee5c7-58e5-46ab-8609-b29f7920ee63.camediaload:hover .layer-color,
.custom-4a0ee5c7-58e5-46ab-8609-b29f7920ee63 .camediaload:hover .layer-color{
    background-color: {{color:layerColorHover}}
}

4a0ee5c7-58e5-46ab-8609-b29f7920ee63.javascript:
var self = this;
var userInput = config.hoverMediaID || config.hoverImageURL || '';
var layer = config['color:layerColor'] || '';
var layerHover = config['color:layerColorHovered'] || '';
var clonedTarget;
var targets;
var hoverImageURL;
var block = self.parent('#' + config.blockID);
var findMediaID = (block.elements[0].className || '').indexOf('camediaload') > -1 ? block : self.parent('#' + config.blockID).find('.camediaload');
var requiresRepeatFindMediaSize = false;
var lastLoadedSizeCheck;
var scrollTimer;


if (layer || layerHover) {

    DOM().new('span').class('abs-fill layer-color').appendTo(findMediaID);
}

if (userInput) {
    function configureMediaFromUserInput() {
        if (userInput.indexOf('http') === 0) {
            hoverImageURL = userInput;
        } else {
            if (findMediaID.exists()) {
                hoverImageURL = findMediaID.attr('data-base') + 'w:' + findMediaID.attr('data-loaded') + '/' + userInput + '.' + findMediaID.attr('data-ext')
                requiresRepeatFindMediaSize = true;
            }
        }
        findAndUpdateAttributeOnMediaElement();
    }
    function findAndUpdateAttributeOnMediaElement() {
        if (!clonedTarget) {
            targets = self.parent('#' + config.blockID).find('.custom-4a0ee5c7-58e5-46ab-8609-b29f7920ee63.camediaload .load-media-element, .custom-4a0ee5c7-58e5-46ab-8609-b29f7920ee63 .camediaload .load-media-element')
            if(targets.exists()){
                clonedTarget = targets.clone(true);
                console.log('targets', targets, 'clone', clonedTarget)
                clonedTarget.attr({id: clonedTarget.attr('id') + '-clone1'}).css({opacity: ''}).addClass('load-media-element-clone').appendTo(targets.parent());
                console.log('found targets!!!')
            }
        } else {
            setTimeout(findAndUpdateAttributeOnMediaElement, 500)
        }
        if (clonedTarget) {
            clonedTarget.css({'background-image': 'url('+hoverImageURL+')'});
        }
    }
    var timer;
    window.addEventListener('resize', function imageSwapOnResize(e){
        clearTimeout(timer);
        clearTimeout(scrollTimer);
        timer = setTimeout(configureMediaFromUserInput, 100);
        scrollTimer = setTimeout(updateMediaURLSresponsive, 100);
    })
    setTimeout(configureMediaFromUserInput, 200)
} else {
    hoverImageURL = findMediaID.attr('data-base') + 'w:' + findMediaID.attr('data-loaded') + '/' + userInput + '.' + findMediaID.attr('data-ext')
    requiresRepeatFindMediaSize = true;
}


function updateMediaURLSresponsive() {
    if (requiresRepeatFindMediaSize) {
        if (findMediaID.attr('data-loaded') !== lastLoadedSizeCheck) {
            hoverImageURL = findMediaID.attr('data-base') + 'w:' + findMediaID.attr('data-loaded') + '/' + userInput + '.' + findMediaID.attr('data-ext')
            if (clonedTarget) {
                clonedTarget.css({'background-image': 'url('+hoverImageURL+')'});
            }
            configureMediaFromUserInput();
            lastLoadedSizeCheck = findMediaID.attr('data-loaded');
        }
    }
}


window.addEventListener('scroll', function(e){
    clearTimeout(scrollTimer);
    scrollTimer = setTimeout(updateMediaURLSresponsive, 10);
})
